from report import add_section, build_report


def test_build_report_returns_only_its_own_titles():
    assert build_report(["intro", "body"]) == ["intro", "body"]


def test_build_report_is_repeatable_within_one_process():
    build_report(["intro", "body"])
    assert build_report(["summary"]) == ["summary"]


def test_add_section_does_not_share_state_between_calls():
    assert add_section("a") == ["a"]
    assert add_section("b") == ["b"]


def test_add_section_appends_to_a_caller_supplied_list():
    sections = ["a"]
    assert add_section("b", sections) == ["a", "b"]
    assert sections == ["a", "b"]

